# frozen_string_literal: true

describe DiscourseVideo::MuxApi do
  let(:url) { "https://api.mux.com/video/v1/uploads" }

  before do
    SiteSetting.discourse_video_mux_token_id = "987654321"
    SiteSetting.discourse_video_mux_token_secret = "abc"
  end

  describe "creating video with mp4 support" do
    before { SiteSetting.discourse_video_enable_mp4_download = true }

    body = {
      new_asset_settings: {
        playback_policy: ["public"],
        mp4_support: "standard",
      },
      cors_origin: "*",
    }

    let!(:creation_stub) do
      stub_request(:post, url).with(
        body: body.to_json,
        headers: {
          "Authorization" => "Basic OTg3NjU0MzIxOmFiYw==",
          "Content-Type" => "application/json",
          "Host" => "api.mux.com",
        },
      ).to_return(status: 200, body: {}.to_json, headers: {})
    end

    it "creates with mp4 support" do
      api = described_class.create_direct_upload
      expect(creation_stub).to have_been_requested.once
    end
  end

  describe "creating video without mp4 support" do
    before { SiteSetting.discourse_video_enable_mp4_download = false }

    body = {
      new_asset_settings: {
        playback_policy: ["public"],
        mp4_support: "none",
      },
      cors_origin: "*",
    }

    let!(:creation_stub) do
      stub_request(:post, url).with(
        body: body.to_json,
        headers: {
          "Authorization" => "Basic OTg3NjU0MzIxOmFiYw==",
          "Content-Type" => "application/json",
          "Host" => "api.mux.com",
        },
      ).to_return(status: 200, body: {}.to_json, headers: {})
    end

    it "creates without mp4 support" do
      api = described_class.create_direct_upload
      expect(creation_stub).to have_been_requested.once
    end
  end
end

# frozen_string_literal: true

describe Guardian do
  let(:user) { Fabricate(:user, trust_level: TrustLevel[1]) }
  let(:user1) { Fabricate(:user, trust_level: TrustLevel[0]) }
  let(:admin) { Fabricate(:user, trust_level: TrustLevel[0], admin: true) }
  let(:moderator) { Fabricate(:user, trust_level: TrustLevel[0], moderator: true) }
  let(:guardian) { Guardian.new(user) }
  let(:guardian1) { Guardian.new(user1) }
  let(:adminGuardian) { Guardian.new(admin) }
  let(:moderatorGuardian) { Guardian.new(moderator) }

  before { SiteSetting.discourse_video_enabled = true }

  describe "can_upload_video?" do
    it "returns true for users having specified trust level" do
      expect(guardian.can_upload_video?).to eq(true)
    end

    it "returns false for users not having specified trust level" do
      expect(guardian1.can_upload_video?).to eq(false)
    end

    it "returns true if user is admin/moderator" do
      expect(adminGuardian.can_upload_video?).to eq(true)

      expect(moderatorGuardian.can_upload_video?).to eq(true)
    end
  end
end

import { click, visit } from "@ember/test-helpers";
import { test } from "qunit";
import { clearToolbarCallbacks } from "discourse/components/d-editor";
import { acceptance } from "discourse/tests/helpers/qunit-helpers";

acceptance("Discourse video disabled", function (needs) {
  needs.user();
  needs.settings({
    discourse_video_enabled: false,
  });
  needs.hooks.beforeEach(() => clearToolbarCallbacks());

  test("doesn't shows upload video icon in composer", async function (assert) {
    await visit("/");
    await click("#create-topic");

    assert
      .dom(".discourse-video-upload")
      .doesNotExist("the upload video button is not available");
  });
});

